service.method:

SELECT
		  USER_ID
		, MENU_PROFILE_CODE
		, USER_TYPE
FROM
	SUSMT
WHERE
		HOUSE_CODE 		= ${session.HOUSE_CODE}
	AND COMPANY_CODE 	= ${session.COMPANY_CODE}	
	AND USER_ID 		= ${USER_ID}


UPDATE SUSMT
   SET
		  CHANGE_DATE    	= ${current.DATE}
		, CHANGE_TIME    	= ${current.TIME}
		, CHANGE_USER_ID  	= ${session.ID}				  
		, USER_NAME_LOC	 	= ${USER_NAME_LOC}
		, USER_NAME_ENG	 	= $S{USER_NAME_ENG}
		, DEPT		      	= ${DEPT}
		, POSITION		  	= $S{POSITION}
		, EMAIL  		    = $S{EMAIL}
		, PHONE           	= $S{PHONE}
		, employee_no       = $S{EMPLOYEE_NO}
		, DEL_FLAG        	= 'N'
		, LANGUAGE			= 'KO'
		, USER_TYPE			= #DB_OWNER#NVL($S{USER_TYPE}, USER_TYPE)
WHERE
	  HOUSE_CODE        	= ${session.HOUSE_CODE}
  AND COMPANY_CODE 			= ${session.COMPANY_CODE}
  AND USER_ID           	= ${USER_ID}
